import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { BadgeComponent } from '@/components/ui/badge';
import { ButtonComponent } from '@/components/ui/button';
import {
    CardComponent,
    CardContentComponent,
    CardDescriptionComponent,
    CardHeaderComponent,
    CardTitleComponent,
} from '@/components/ui/card';
import {
    EmptyComponent,
    EmptyDescriptionComponent,
    EmptyHeaderComponent,
    EmptyTitleComponent,
} from '@/components/ui/empty';
import { SkeletonComponent } from '@/components/ui/skeleton';

interface Project {
    readonly id: string;
    readonly name: string;
    readonly status: string;
}

/**
 * The state machine every list gets wrong once.
 *
 * A data view has three states, not one, and they are not interchangeable: a
 * spinner where a skeleton belongs makes the layout jump when data lands, and
 * an empty grid where an empty state belongs reads as a bug. Model the state
 * explicitly — `loading` first, then `items.length === 0`, then the list — and
 * render skeletons with the same shape as the real cards so nothing reflows.
 */
@Component({
    selector: 'app-loading-to-loaded-list',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        BadgeComponent,
        ButtonComponent,
        CardComponent,
        CardContentComponent,
        CardDescriptionComponent,
        CardHeaderComponent,
        CardTitleComponent,
        EmptyComponent,
        EmptyDescriptionComponent,
        EmptyHeaderComponent,
        EmptyTitleComponent,
        SkeletonComponent,
    ],
    template: `
    <div class="space-y-4">
      <div class="flex flex-wrap items-center gap-2">
        <ui-button (clicked)="load()" data-testid="load">Load</ui-button>
        <ui-button variant="outline" (clicked)="loadEmpty()" data-testid="load-empty">
          Load nothing
        </ui-button>
      </div>

      @if (loading()) {
        <div class="grid gap-4 sm:grid-cols-2" data-testid="loading">
          @for (placeholder of placeholders; track placeholder) {
            <ui-card>
              <ui-card-header>
                <ui-skeleton class="h-5 w-40" />
                <ui-skeleton class="h-4 w-56" />
              </ui-card-header>
              <ui-card-content>
                <ui-skeleton class="h-4 w-24" />
              </ui-card-content>
            </ui-card>
          }
        </div>
      } @else if (isEmpty()) {
        <ui-empty data-testid="empty">
          <ui-empty-header>
            <ui-empty-title>No projects yet</ui-empty-title>
            <ui-empty-description>
              Create one and it will show up here.
            </ui-empty-description>
          </ui-empty-header>
        </ui-empty>
      } @else {
        <div class="grid gap-4 sm:grid-cols-2" data-testid="loaded">
          @for (project of projects(); track project.id) {
            <ui-card>
              <ui-card-header>
                <ui-card-title>{{ project.name }}</ui-card-title>
                <ui-card-description>Updated moments ago</ui-card-description>
              </ui-card-header>
              <ui-card-content>
                <ui-badge variant="secondary">{{ project.status }}</ui-badge>
              </ui-card-content>
            </ui-card>
          }
        </div>
      }
    </div>
  `,
})
export class LoadingToLoadedListComponent {
    protected readonly placeholders: readonly number[] = [1, 2];
    protected readonly loading = signal(false);
    protected readonly projects = signal<readonly Project[]>([]);

    protected readonly isEmpty = computed(() => this.projects().length === 0);

    protected load(): void {
        this.loading.set(true);
        this.projects.set([
            { id: 'a', name: 'Design system', status: 'Active' },
            { id: 'b', name: 'Billing rewrite', status: 'Paused' },
        ]);
        this.loading.set(false);
    }

    protected loadEmpty(): void {
        this.loading.set(true);
        this.projects.set([]);
        this.loading.set(false);
    }
}

import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { ButtonComponent } from '@/components/ui/button';
import { KbdComponent } from '@/components/ui/kbd';
import {
    CommandComponent,
    CommandDialogComponent,
    CommandEmptyComponent,
    CommandGroupComponent,
    CommandInputComponent,
    CommandItemComponent,
    CommandListComponent,
} from '@/components/ui/command';

interface PaletteAction {
    readonly id: string;
    readonly label: string;
    readonly group: string;
}

/**
 * The keyboard entry point power users look for first.
 *
 * `ui-command-dialog` is `ui-command` inside a modal, so the filtering,
 * highlight and Enter-to-select behaviour is the same whether the palette is
 * inline or in an overlay. Bind `open` two-way and drive it from a host
 * keydown listener; the dialog handles Escape itself.
 */
@Component({
    selector: 'app-searchable-command-palette',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        ButtonComponent,
        KbdComponent,
        CommandComponent,
        CommandDialogComponent,
        CommandEmptyComponent,
        CommandGroupComponent,
        CommandInputComponent,
        CommandItemComponent,
        CommandListComponent,
    ],
    template: `
    <ui-button variant="outline" (clicked)="open.set(true)" data-testid="open-palette">
      Search actions
      <ui-kbd class="ms-2">Ctrl K</ui-kbd>
    </ui-button>

    <ui-command-dialog [(open)]="open">
      <ui-command>
        <ui-command-input placeholder="Type a command…" />
        <ui-command-list>
          <ui-command-empty>Nothing matches that.</ui-command-empty>
          @for (group of groups; track group) {
            <ui-command-group [heading]="group">
              @for (action of actionsIn(group); track action.id) {
                <ui-command-item [value]="action.label" (selectItem)="run(action)">
                  {{ action.label }}
                </ui-command-item>
              }
            </ui-command-group>
          }
        </ui-command-list>
      </ui-command>
    </ui-command-dialog>

    <p data-testid="last-action">{{ lastAction() }}</p>
  `,
})
export class SearchableCommandPaletteComponent {
    protected readonly open = signal(false);
    protected readonly lastAction = signal('');

    protected readonly actions: readonly PaletteAction[] = [
        { id: 'new', label: 'New document', group: 'Create' },
        { id: 'invite', label: 'Invite teammate', group: 'Create' },
        { id: 'theme', label: 'Toggle dark mode', group: 'Preferences' },
        { id: 'shortcuts', label: 'Keyboard shortcuts', group: 'Preferences' },
    ];

    protected readonly groups: readonly string[] = ['Create', 'Preferences'];

    protected actionsIn(group: string): readonly PaletteAction[] {
        return this.actions.filter(action => action.group === group);
    }

    protected run(action: PaletteAction): void {
        this.lastAction.set(action.id);
        this.open.set(false);
    }
}

import { ChangeDetectionStrategy, Component, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ButtonComponent } from '@/components/ui/button';
import { CheckboxComponent } from '@/components/ui/checkbox';
import { InputComponent } from '@/components/ui/input';
import { LabelComponent } from '@/components/ui/label';
import {
    SheetComponent,
    SheetContentComponent,
    SheetDescriptionComponent,
    SheetFooterComponent,
    SheetHeaderComponent,
    SheetTitleComponent,
    SheetTriggerComponent,
} from '@/components/ui/sheet';

/**
 * The form pattern that survives an accessibility audit.
 *
 * Three things do the work: every `ui-input` has an `id` its `ui-label` points
 * at, the error message is rendered next to the field it describes rather than
 * in a summary, and submit stays disabled while the group is invalid so the
 * failure state is never a surprise. `ui-sheet` keeps the surrounding page
 * visible, which is what makes a side sheet the right container for an edit
 * form rather than a modal dialog.
 */
@Component({
    selector: 'app-validated-form-in-a-sheet',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        ReactiveFormsModule,
        ButtonComponent,
        CheckboxComponent,
        InputComponent,
        LabelComponent,
        SheetComponent,
        SheetContentComponent,
        SheetDescriptionComponent,
        SheetFooterComponent,
        SheetHeaderComponent,
        SheetTitleComponent,
        SheetTriggerComponent,
    ],
    template: `
    <ui-sheet #sheet>
      <ui-sheet-trigger>
        <ui-button data-testid="open-sheet">Invite teammate</ui-button>
      </ui-sheet-trigger>
      <ui-sheet-content side="right">
        <ui-sheet-header>
          <ui-sheet-title>Invite a teammate</ui-sheet-title>
          <ui-sheet-description>They get an email with a join link.</ui-sheet-description>
        </ui-sheet-header>

        <form [formGroup]="form" (ngSubmit)="submit(sheet)" class="space-y-4 p-4">
          <div class="space-y-1">
            <ui-label for="invite-email">Email</ui-label>
            <ui-input id="invite-email" type="email" formControlName="email" />
            @if (emailInvalid()) {
              <p class="text-sm text-destructive" data-testid="email-error">
                Enter a valid email address.
              </p>
            }
          </div>

          <div class="flex items-center gap-2">
            <ui-checkbox id="invite-admin" formControlName="admin" ariaLabel="Grant admin access" />
            <ui-label for="invite-admin">Grant admin access</ui-label>
          </div>

          <ui-sheet-footer>
            <ui-button type="submit" [disabled]="form.invalid" data-testid="submit">
              Send invite
            </ui-button>
          </ui-sheet-footer>
        </form>
      </ui-sheet-content>
    </ui-sheet>

    <p data-testid="invited">{{ invited() }}</p>
  `,
})
export class ValidatedFormInASheetComponent {
    protected readonly invited = signal('');

    protected readonly form = new FormGroup({
        email: new FormControl('', { nonNullable: true, validators: [Validators.required, Validators.email] }),
        admin: new FormControl(false, { nonNullable: true }),
    });

    protected emailInvalid(): boolean {
        const control = this.form.controls.email;
        return control.invalid && control.touched;
    }

    protected submit(sheet: SheetComponent): void {
        if (this.form.invalid) return;
        this.invited.set(this.form.controls.email.value);
        sheet.hide();
    }
}
